class Solution { vector<vector<int>> score;vector<int> memo;int dfs(int mask){if(mask==(int)memo.size()-1)return 0;int& result=memo[mask];if(result>=0)return result;int student=__builtin_popcount((unsigned)mask);result=0;for(int mentor=0;mentor<(int)score.size();++mentor)if(!(mask&(1<<mentor)))result=max(result,score[student][mentor]+dfs(mask|(1<<mentor)));return result;}public: int maxCompatibilitySum(vector<vector<int>>& students,vector<vector<int>>& mentors){int n=students.size();score.assign(n,vector<int>(n));for(int i=0;i<n;++i)for(int j=0;j<n;++j)for(int q=0;q<(int)students[i].size();++q)score[i][j]+=students[i][q]==mentors[j][q];memo.assign(1<<n,-1);return dfs(0);} };
